        long aInv = modPow(a, p - 2, p);

        long count = 0;

        // Iterate over all possible residues r mod p
        for (long r = 0; r < p; r++) {
            // Compute a^r mod p
            long ar = modPow(a, r, p);
            // Compute a^{-r} mod p
            long arInv = modPow(ar, p - 2, p);
            // Compute c = b * a^{-r} mod p
            long c = b * arInv % p;

            // Solve n ≡ c mod p
            // n = c + k*p, k >= 0
            // Also n ≡ r mod (p-1)
            // So c + k*p ≡ r mod (p-1)
            // k*p ≡ (r - c) mod (p-1)
            long rhs = (r - c) % (p - 1);
            if (rhs < 0) rhs += (p - 1);

            // Solve k*p ≡ rhs mod (p-1)
            // p and p-1 are coprime, so p has an inverse mod (p-1)
            long pMod = p % (p - 1);
            long invP = modPow(pMod, (p - 1) - 1, p - 1); // Fermat's little theorem
