            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static void precomputeInverses() {
        inv = new long[(int) p];
        inv[1] = 1;
        for (int i = 2; i < p; i++) {
            inv[i] = (p - (p / i) * inv[(int) (p % i)] % p) % p;
        }
    }

    static long findDiscreteLog(long target) {
        long m = (long) Math.sqrt(p - 1) + 1;
        Map<Long, Long> table = new HashMap<>();
        long giantStep = powMod(a, m, p);
        long current = 1;
        for (long j = 0; j < m; j++) {
            if (!table.containsKey(current)) {
                table.put(current, j);
            }
            current = (current * giantStep) % p;
        }
        long factor = powMod(a, p - 1 - m, p);
        current = target;
        for (long i = 0; i < m; i++) {
            if (table.containsKey(current)) {
                long j = table.get(current);
                long k = i * m + j;
                if (k < p - 1) return k;
            }
            current = (current * factor) % p;
        }
        return -1;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        a = Long.parseLong(st.nextToken());
        b = Long.parseLong(st.nextToken());
        p = Long.parseLong(st.nextToken());
        x = Long.parseLong(st.nextToken());

        precomputeInverses();

        long count = 0;
        long cycle = p - 1;
        long m = x / cycle;
        long r = x % cycle;

        for (long k = 0; k < cycle; k++) {
            long ak = powMod(a, k, p);
            long lhs = (b * inv[(int) ak]) % p;
            long d = gcd(k, cycle);
            if (lhs == 0) continue;
            if (powMod(lhs, (p - 1) / d, p) != 1) continue;
            long n0 = findDiscreteLog(lhs);
            if (n0 == -1) continue;
            long step = cycle / d;
            long first = n0 % step;
            if (first < 0) first += step;
            long lastInCycle = first + ((cycle - 1 - first) / step) * step;
            if (first > cycle - 1) continue;
            long totalInCycle = (lastInCycle - first) / step + 1;
            long cnt = 0;
            if (first <= r) {
                long lastInR = first + ((r - first) / step) * step;
                if (lastInR >= first) {
                    cnt += (lastInR - first) / step + 1;
                }
            }
            cnt += (m - 1) * totalInCycle;
            if (first <= r) {
                cnt += totalInCycle;
            } else {
                cnt += 0;
            }
            count += cnt;
        }

        System.out.println(count);
