        for (int i = 1; i <= p; i++) {
            pow[i] = pow[i - 1] * a % p;
        }

        long count = 0;
        // Check all possible residues mod p-1 for exponent
        for (int r = 0; r < p - 1; r++) {
            // Solve n ≡ r mod (p-1)
            // n = r + k*(p-1)
            // Find smallest n >= 1 such that n ≡ r mod (p-1)
            long n0;
            if (r == 0) {
                n0 = p - 1;
            } else {
                n0 = r;
            }
            if (n0 > x) continue;

            // Now check if there exists k >= 0 such that n = n0 + k*(p-1) <= x
            // and n * a^n ≡ b mod p
            // a^n = a^(n0 + k*(p-1)) = a^n0 * (a^(p-1))^k ≡ a^n0 mod p
            // So equation becomes n * a^n0 ≡ b mod p
            // n ≡ b * inv(a^n0) mod p
            long an0 = pow[(int)n0];
            if (an0 == 0) continue;
            long inv_an0 = inv[(int)an0];
            long target = b * inv_an0 % p;
            if (target < 0) target += p;

            // n ≡ target mod p
            // n = n0 + k*(p-1)
            // n0 + k*(p-1) ≡ target mod p
            // k*(p-1) ≡ (target - n0) mod p
            long rhs = (target - n0 % p + p) % p;
            long coeff = (p - 1) % p;
            long inv_coeff = inv[(int)coeff];
            long k0 = rhs * inv_coeff % p;

            // n = n0 + k0*(p-1)
            long n_start = n0 + k0 * (p - 1);
            if (n_start > x) continue;

            // Count valid n in [1, x]
            long period = p * (p - 1);
            long first = n_start;
            if (first < 1) {
                long diff = (1 - first + period - 1) / period;
                first += diff * period;
            }
            if (first > x) continue;

            long last = first + ((x - first) / period) * period;
            count += (last - first) / period + 1;
        }

        System.out.println(count);
    }
