        // a^d ≡ target mod p
        // We need to find d such that a^d ≡ target mod p
        // Since a is a primitive root? Not necessarily. But we can use baby-step giant-step.

        // Precompute a^d for d in [0, phi)
        // But phi can be up to 1e6+2, so we can precompute a^d mod p for d in [0, phi)
        // and store in an array logTable where logTable[a^d mod p] = d

        long[] logTable = new long[(int) p];
        Arrays.fill(logTable, -1);
        long cur = 1;
        for (int d = 0; d < phi; d++) {
